\begin{tikzpicture}[x=6.4mm,y=5mm,font=\rmfamily\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{graphGrid}{HTML}{CCCCCC}
\foreach \x in {4.5,5.5,...,10.5} {\draw[draw=graphGrid,line width=0.15pt,dash pattern=on 1pt off 1.5pt] (\x,0)--(\x,9);}
\foreach \y in {0.5,1.5,...,8.5} {\draw[draw=graphGrid,line width=0.15pt,dash pattern=on 1pt off 1.5pt] (4,\y)--(11,\y);}
\foreach \x in {4,5,...,11} {\draw[draw=graphGrid,line width=0.25pt,dash pattern=on 1pt off 1.5pt] (\x,0)--(\x,9);}
\foreach \y in {0,1,...,9} {\draw[draw=graphGrid,line width=0.25pt,dash pattern=on 1pt off 1.5pt] (4,\y)--(11,\y);}
\foreach \score/\frequency in {5/5,6/9,7/8,8/4,9/0,10/2} {\draw[black,line width=0.8pt] ({\score-0.5},0) rectangle ({\score+0.5},\frequency);}
\draw[black,line width=0.5pt] (4,0)--(11.1,0);
\draw[black,line width=0.5pt] (4,0)--(4,9.3);
\foreach \x in {5,6,...,10} {\draw[black,line width=0.4pt] (\x,0)--++(0,-1mm) node[anchor=north,inner sep=1pt,font=\rmfamily\fontsize{8.5}{10}\selectfont] {\special{dvisvgm:raw <g data-graph-text="tick">}\x\special{dvisvgm:raw </g>}};}
\foreach \y in {0,1,...,9} {\draw[black,line width=0.4pt] (4,\y)--++(-1mm,0) node[anchor=east,inner sep=1pt,font=\rmfamily\fontsize{8.5}{10}\selectfont] {\special{dvisvgm:raw <g data-graph-text="tick">}\y\special{dvisvgm:raw </g>}};}
\node[anchor=north,font=\rmfamily\itshape\fontsize{10}{12}\selectfont] at (7.5,-1.5) {Shoe size};
\node[rotate=90,font=\rmfamily\itshape\fontsize{10}{12}\selectfont] at (2.5,4.5) {Frequency};
\end{tikzpicture}
